export function PingPill({ ms, online = true, class: cls }) {
  const ok = online && Number.isFinite(ms);
  const tier = !ok ? 'off' : ms < 60 ? 'low' : ms < 200 ? 'medium' : 'high';
  // v2.7.6：延迟胶囊 = 打开服务器面板（连接路径已移入面板「诊断」行）
  const openServer = () => { try { window.__SP_SHELL && window.__SP_SHELL.openPanel && window.__SP_SHELL.openPanel('servers'); } catch (e) { /* shell bridge absent */ } };
  return html`<span class=${cx('ping', `ping--${tier}`, cls)} title=${ok ? `当前延迟 ${ms}ms · 点按切换服务器` : '点按切换服务器'}
    role="button" tabindex="0" onClick=${openServer} onKeyDown=${(e) => { if (e.key === 'Enter' || e.key === ' ') openServer(); }}>

